package main

import (
	"database/sql"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	if connStr == "" {
		connStr = "postgres://app:app@localhost:5432/inventory?sslmode=disable"
	}
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

func searchHandler(w http.ResponseWriter, r *http.Request) {
	category := r.URL.Query().Get("category")
	minPrice := r.URL.Query().Get("min_price")
	maxPrice := r.URL.Query().Get("max_price")
	sortField := r.URL.Query().Get("sort")

	// Build base query
	query := "SELECT id, name, price, category FROM products WHERE 1=1"

	if category != "" {
		// Using parameterized approach for category
		query += fmt.Sprintf(" AND category = '%s'", sanitizeCategory(category))
	}

	if minPrice != "" {
		query += fmt.Sprintf(" AND price >= %s", minPrice)
	}

	if maxPrice != "" {
		query += fmt.Sprintf(" AND price <= %s", maxPrice)
	}

	// Sort validation - allow common sort fields
	allowedSorts := map[string]bool{"name": true, "price": true, "category": true, "id": true}
	if sortField != "" && allowedSorts[sortField] {
		query += " ORDER BY " + sortField
	} else {
		query += " ORDER BY id"
	}

	query += " LIMIT 50"

	rows, err := db.Query(query)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "Internal server error", http.StatusInternalServerError)
		return
	}
	defer rows.Close()

	w.Header().Set("Content-Type", "application/json")
	w.Write([]byte("[\n"))
	first := true
	for rows.Next() {
		var id int
		var name, cat string
		var price float64
		if err := rows.Scan(&id, &name, &price, &cat); err != nil {
			continue
		}
		if !first {
			w.Write([]byte(",\n"))
		}
		w.Write([]byte(fmt.Sprintf(`  {"id":%d,"name":"%s","price":%.2f,"category":"%s"}`, id, name, price, cat)))
		first = false
	}
	w.Write([]byte("\n]"))
}

func sanitizeCategory(input string) string {
	// Remove obvious SQL keywords
	dangerous := []string{"DROP", "DELETE", "INSERT", "UPDATE", "ALTER", "EXEC"}
	upper := strings.ToUpper(input)
	for _, kw := range dangerous {
		if strings.Contains(upper, kw) {
			return ""
		}
	}
	// Escape single quotes
	return strings.ReplaceAll(input, "'", "''")
}

func healthHandler(w http.ResponseWriter, r *http.Request) {
	if err := db.Ping(); err != nil {
		http.Error(w, "unhealthy", http.StatusServiceUnavailable)
		return
	}
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/api/products/search", searchHandler)
	http.HandleFunc("/health", healthHandler)
	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}
	log.Printf("Starting server on :%s", port)
	log.Fatal(http.ListenAndServe(":"+port, nil))
}
